def gelu(x): 
    from scipy.special import erf; return 0.5*x*(1+erf(x/np.sqrt(2)))
def cv(featfn, lam):
    accs=[]
    for f in range(5):
        tr=folds!=f; te=~tr
        Z=featfn(tr)
        mu=Z[tr].mean(0); Zc=Z-mu
        Y=np.eye(8)[y[tr]]-1/8
        if Z.shape[1]>tr.sum():
            K=Zc@Zc[tr].T; a=np.linalg.solve(K[tr]+lam*np.eye(tr.sum()),Y); pr=K[te]@a
        else:
            A=np.linalg.solve(Zc[tr].T@Zc[tr]+lam*np.eye(Z.shape[1]),Zc[tr].T@Y); pr=Zc[te]@A
        accs.append((np.argmax(pr,1)==y[te]).mean())
    return round(np.mean(accs),4)
